import { cacheLife, cacheTag } from 'next/cache'
import { getAllProducts } from '@/lib/db'

// Shared, cached read path for the product catalog.
//
// Any view (admin or storefront) that needs catalog data should read it through
// this function so they all share one cache entry under the `"products"` tag.
// That makes browsing fast — repeat requests are served from cache instead of
// re-querying the ERP/PIM — and lets a single `revalidateTag("products", "max")`
// refresh every dependent view at once.
export async function getProducts() {
  'use cache'
  // Long lived on purpose: the catalog only changes when upstream ERP/PIM data
  // changes, and those changes arrive via on-demand `revalidateTag` rather than
  // on a timer. A long `cacheLife` avoids needless re-querying for read-heavy
  // browsing.
  cacheLife('days')
  cacheTag('products')

  return getAllProducts()
}

